    advWindow->UpdateResourceDisplay(1, 1);
    status = STATUS_ACTIVE;
    priority = newPriority;
    id = 0x400;
    strcpy(cMgrName,
           DATA_COMPGEN(0x00660294, advManagerMgrName, "advManager"));
